queries.typeql:
with fun tied_vote_exists() -> boolean:
  match $_ isa candidacy, has tied_vote_winner true;
  return check;
match
let $exists = tied_vote_exists();

match $pa isa party, has party_name $name; candidacy (party: $pa); reduce $candidacies = count groupby $pa, $name; sort $candidacies desc; limit 1; fetch {
  "party": $name,
  "candidacies": $candidacies
};
